from lib import *
from fractions import Fraction as F
LESSON = 'ស្វ័យគុណ'

def pw(a, n):                       # power as TeX, parenthesise negative / fraction bases
    a = F(a)
    if a.denominator != 1: b = f'\\left({frac(a)}\\right)'
    elif a < 0: b = f'({a.numerator})'
    else: b = str(a.numerator)
    return f'{b}^{{{n}}}'
def V(a, n): return F(a) ** n       # exact value
def Mv(f): return M(frac(F(f)) if F(f).denominator != 1 else num(int(F(f))))
def exp(a, n): return M(f'{a}^{{{n}}}')
def std(A, n): return f'{A}\\times10^{{{n}}}'
def uniqv(ans, cand, k=3, fmt=Mv):
    out = []
    for c in cand:
        c = F(c)
        if c != F(ans) and c not in out: out.append(c)
    d = 1
    while len(out) < k:
        c = F(ans) + d; d += 1
        if c not in out and c != F(ans): out.append(c)
    return [fmt(c) for c in out[:k]]
def pm(x): return M(x)

